fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let down: i32 = host::display::pointer_down();
    let mut hd: i32 = host::display::state_get(2);
    if down == 1 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        host::display::state_set(8 + (hd & 15), px * 65536 + py);
        hd = hd + 1;
        host::display::state_set(2, hd);
    }
    let pal = [0xff6ad5, 0x6adfff, 0xfff06a, 0x8aff6a];
    host::display::clear(0x08060c);
    let mut k: i32 = 0;
    while k < 16 {
        let v: i32 = host::display::state_get(8 + k);
        if v != 0 {
            let x: i32 = v / 65536;
            let y: i32 = v % 65536;
            let dx: i32 = x - cx;
            let dy: i32 = y - cy;
            let age: i32 = (hd - 1 - k) & 15;
            let s: i32 = 10 - age / 2;
            let c: i32 = pal[k & 3];
            host::display::fill_rect(cx + dx - s / 2, cy + dy - s / 2, s, s, c);
            host::display::fill_rect(cx - dx - s / 2, cy + dy - s / 2, s, s, c);
            host::display::fill_rect(cx + dx - s / 2, cy - dy - s / 2, s, s, c);
            host::display::fill_rect(cx - dx - s / 2, cy - dy - s / 2, s, s, c);
            host::display::fill_rect(cx + dy - s / 2, cy + dx - s / 2, s, s, c);
            host::display::fill_rect(cx - dy - s / 2, cy + dx - s / 2, s, s, c);
            host::display::fill_rect(cx + dy - s / 2, cy - dx - s / 2, s, s, c);
            host::display::fill_rect(cx - dy - s / 2, cy - dx - s / 2, s, s, c);
        }
        k = k + 1;
    }
    host::display::draw_line(cx, 0, cx, h - 1, 0x181424);
    host::display::draw_line(0, cy, w - 1, cy, 0x181424);
    host::display::present();
}
